def run(self):
        """运行服务端主循环"""
        self._running = True
        logger.info("IPC Server started, listening on stdin...")

        for line in sys.stdin:
            line = line.strip()
            if not line:
                continue

            try:
                request = json.loads(line)
                response = self.handle(request)

                if response:
                    print(json.dumps(response), flush=True)

            except json.JSONDecodeError as e:
                logger.error(f"JSON decode error: {e}, raw data: {line[:200]}")
                error_response = self.protocol.error_response(
                    None, -32600, f"Parse error: {e}"
                )
                print(json.dumps(error_response), flush=True)

            except Exception as e:
                logger.exception("Server loop error")
                error_response = self.protocol.error_response(
                    None, -32603, f"{type(e).__name__}: {str(e)[:200]}"
                )
                print(json.dumps(error_response), flush=True)

        self._running = False
        logger.info("IPC Server stopped")

def suppress_errors(
    log_message: str = None,
    log_level: str = "debug",
    raise_on: tuple[Type[Exception], ...] = None,
):
    """
    装饰器：抑制函数异常

    Args:
        log_message: 异常时的日志消息
        log_level: 日志级别
        raise_on: 需要重新抛出的异常类型

    Example:
        @suppress_errors(log_message="清理临时文件失败")
        def cleanup():
            ...
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if raise_on and isinstance(e, raise_on):
                    raise

                if log_message:
                    log_func = getattr(logger, log_level, logger.debug)
                    log_func(f"{log_message}: {e}")

                return None
        return wrapper
    return decorator

