class Router:
    """
    RPC 方法路由器
    将 namespace.method 路由到对应的处理函数
    """

    def __init__(self):
        self._handlers: Dict[str, Callable] = {}

    def register(
        self,
        namespace: str,
        method: str,
        handler: Callable
    ):
        """
        注册处理函数

        Args:
            namespace: 命名空间，如 "project", "analyze"
            method: 方法名，如 "list", "create"
            handler: 处理函数
        """
        full_name = f"{namespace}.{method}"
        self._handlers[full_name] = handler
        logger.debug(f"Registered RPC handler: {full_name}")

    def resolve(self, full_name: str) -> Optional[Callable]:
        """解析方法名到处理函数"""
        return self._handlers.get(full_name)

    def list_methods(self) -> list:
        """列出所有已注册的方法"""
        return list(self._handlers.keys())

    def unregister(self, namespace: str, method: str):
        """取消注册"""
        full_name = f"{namespace}.{method}"
        self._handlers.pop(full_name, None)

def get_project(self, project_id: str) -> Optional[Dict[str, Any]]:
        """获取项目"""
        with self._get_conn() as conn:
            row = conn.execute(
                "SELECT * FROM projects WHERE id = ?", (project_id,)
            ).fetchone()

            if row:
                return self._row_to_project(row)
        return None

def get_project_by_path(self, path: str) -> Optional[Dict[str, Any]]:
        """通过路径获取项目"""
        with self._get_conn() as conn:
            row = conn.execute(
                "SELECT * FROM projects WHERE path = ?", (path,)
            ).fetchone()

            if row:
                return self._row_to_project(row)
        return None

def delete_missing_videos(self, project_id: str) -> int:
        """删除不存在的视频记录"""
        import os
        videos = self.get_videos(project_id)
        deleted = 0

        with self._get_conn() as conn:
            for video in videos:
                if not os.path.exists(video["path"]):
                    conn.execute("DELETE FROM videos WHERE id = ?", (video["id"],))
                    deleted += 1

        if deleted > 0:
            logger.debug(f"[DB] Deleted {deleted} missing videos for project {project_id}")
        return deleted

def _row_to_project(self, row: sqlite3.Row) -> Dict[str, Any]:
        """将数据库行转换为项目字典"""
        return {
            "id": row["id"],
            "name": row["name"],
            "path": row["path"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
            "episode_count": row["episode_count"],
            "status": row["status"],
            "settings": json.loads(row["settings"]) if row["settings"] else {}
        }

def get_database() -> Database:
    """获取全局数据库实例"""
    global _db
    if _db is None:
        _db = Database()
    return _db

def _ensure_index(self) -> None:
        """确保索引文件存在"""
        if not self.index_file.exists():
            self.index_file.write_text("[]", encoding="utf-8")

def _load_index(self) -> List[Dict]:
        """加载项目索引"""
        try:
            content = self.index_file.read_text(encoding="utf-8")
            projects = json.loads(content)
            logger.debug(f"[Index] Loaded {len(projects)} projects from {self.index_file}")
            return projects
        except json.JSONDecodeError as e:
            logger.error(f"Invalid JSON in index file: {e}")
            return []
        except (OSError, PermissionError, FileNotFoundError) as e:
            logger.error(f"Failed to read index file: {e}")
            return []

def _save_index(self, projects: List[Dict]) -> None:
        """保存项目索引"""
        try:
            content = json.dumps(projects, ensure_ascii=False, indent=2)
            self.index_file.write_text(content, encoding="utf-8")
            logger.debug(f"[Index] Saved {len(projects)} projects to {self.index_file}")
        except (OSError, PermissionError) as e:
            logger.error(f"Failed to save index file: {e}")
            raise

def get_project(self, project_id: str) -> Optional[ProjectMeta]:
        """获取指定项目"""
        projects = self._load_index()
        logger.debug(f"[Index] Looking for project {project_id}, index has {len(projects)} projects")
        for p in projects:
            if p["id"] == project_id:
                logger.debug(f"[Index] Found project: {p['name']} at {p['path']}")
                return ProjectMeta(**p)
        logger.warning(f"[Index] Project {project_id} NOT FOUND in index")
        return None

def _save_meta(self, project: ProjectMeta) -> None:
        """保存项目元数据到 meta.json"""
        try:
            meta_file = Path(project.path) / "meta.json"
            meta_file.write_text(
                json.dumps(project.to_dict(), ensure_ascii=False, indent=2),
                encoding="utf-8"
            )
        except (OSError, PermissionError) as e:
            logger.error(f"Failed to save project meta: {e}")
            raise

def _scan_videos_dir(self, project_id: str, videos_dir: Path) -> Dict[str, int]:
        """扫描视频目录，同步 videos.json 索引"""
        project = self.get_project(project_id)
        if not project:
            return {"found": 0, "removed": 0, "missing": 0}

        project_path = Path(project.path)
        videos_file = project_path / "videos.json"

        # 读取已存在的视频记录
        if videos_file.exists():
            try:
                existing_videos = json.loads(videos_file.read_text(encoding="utf-8"))
            except json.JSONDecodeError:
                existing_videos = []
        else:
            existing_videos = []

        # 建立现有记录的路径映射（key 是文件路径）
        existing_map: Dict[str, Dict] = {v.get("path", ""): v for v in existing_videos}

        # 扫描目录中实际的视频文件
        scanned_paths: Set[str] = set()
        found_count = 0

        try:
            dir_iter = videos_dir.iterdir()
        except (OSError, PermissionError) as e:
            logger.error(f"Failed to iterate videos directory: {e}")
            return {"found": 0, "removed": 0, "missing": 0}

        for file_path in dir_iter:
            try:
                if file_path.is_file() and file_path.suffix.lower() in self.VIDEO_EXTENSIONS:
                    scanned_paths.add(str(file_path))
                    # 用路径匹配，而非文件名
                    if str(file_path) not in existing_map:
                        # 新发现的视频文件
                        video_id = str(uuid.uuid4())
                        now = datetime.now().isoformat()
                        try:
                            file_size = file_path.stat().st_size
                        except (OSError, PermissionError):
                            file_size = 0
                        video_info = VideoInfo(
                            id=video_id,
                            name=file_path.stem,
                            path=str(file_path),
                            size=file_size,
                            duration=0.0,
                            format=file_path.suffix.lstrip("."),
                            imported_at=now,
                        )
                        existing_videos.append(video_info.to_dict())
                        found_count += 1
                        logger.info(f"Discovered new video during scan: {file_path.name}")
            except (OSError, PermissionError) as e:
                logger.warning(f"Failed to process file {file_path}: {e}")
                continue

        # 移除已不存在于磁盘的视频记录
        before = len(existing_videos)
        existing_videos = [v for v in existing_videos if v.get("path", "") in scanned_paths]
        removed_count = before - len(existing_videos)

        # 检查那些仍保留但文件可能不可读的记录
        stats_by_path: Dict[str, int] = {}
        missing_count = 0
        for v in existing_videos:
            p = v.get("path", "")
            if p:
                p_obj = Path(p)
                if not p_obj.exists():
                    missing_count += 1

        # 更新项目元数据
        project.episode_count = len(existing_videos)
        if found_count > 0 or removed_count > 0:
            logger.info(
                f"Sync result for {project_id}: "
                f"+{found_count} new, -{removed_count} removed, "
                f"{missing_count} missing on disk"
            )

        # 保存更新的视频列表
        try:
            videos_file.write_text(
                json.dumps(existing_videos, ensure_ascii=False, indent=2),
                encoding="utf-8"
            )
        except (OSError, PermissionError) as e:
            logger.error(f"Failed to save videos.json: {e}")

        return {
            "found": found_count,
            "removed": removed_count,
            "missing": missing_count,
        }

def get_videos(self, project_id: str) -> List[VideoInfo]:
        """获取项目的视频列表"""
        project = self.get_project(project_id)
        if not project:
            return []

        project_path = Path(project.path)
        videos_file = project_path / "videos.json"

        if not videos_file.exists():
            return []

        try:
            videos_data = json.loads(videos_file.read_text(encoding="utf-8"))
            return [VideoInfo(**v) for v in videos_data]
        except (json.JSONDecodeError, IOError):
            return []

def get_manager() -> ProjectManager:
    """获取全局项目管理器"""
    global _manager
    if _manager is None:
        _manager = ProjectManager()
    return _manager

def get_project(self, project_id: str) -> Optional[ProjectMeta]:
        """获取指定项目"""
        logger.debug(f"[DB] Looking for project {project_id}")
        project_data = self.db.get_project(project_id)
        if project_data:
            logger.debug(f"[DB] Found project: {project_data['name']}")
            return ProjectMeta(**project_data)
        logger.warning(f"[DB] Project {project_id} NOT FOUND")
        return None

def get_project_by_path(self, path: str) -> Optional[ProjectMeta]:
        """通过路径获取项目"""
        project_data = self.db.get_project_by_path(path)
        if project_data:
            return ProjectMeta(**project_data)
        return None

def _save_meta(self, project: ProjectMeta) -> None:
        """保存项目元数据到 meta.json"""
        try:
            meta_file = Path(project.path) / "meta.json"
            meta_file.write_text(
                json.dumps(project.to_dict(), ensure_ascii=False, indent=2),
                encoding="utf-8"
            )
        except (OSError, PermissionError) as e:
            logger.error(f"Failed to save project meta: {e}")

def _scan_videos_dir(self, project_id: str, videos_dir: Path) -> Dict[str, int]:
        """
        扫描视频目录（可选功能）

        注意：现在 videos/ 目录是可选的，主要用于用户想把视频放在项目目录下的场景
        大部分情况下用户直接导入外部文件，不需要扫描
        """
        # 如果 videos/ 目录不存在，跳过扫描
        if not videos_dir.exists():
            logger.debug(f"[DB] Videos directory not exists, skip scan: {videos_dir}")
            return {"found": 0, "removed": 0, "missing": 0}

        found_count = 0
        scanned_paths = set()

        # 获取数据库中已有的视频
        existing_videos = self.db.get_videos(project_id)
        existing_paths = {v["path"]: v for v in existing_videos}

        # 扫描目录
        try:
            for file_path in videos_dir.rglob("*"):  # 递归扫描
                if file_path.is_file() and file_path.suffix.lower() in self.VIDEO_EXTENSIONS:
                    str_path = str(file_path)
                    scanned_paths.add(str_path)

                    if str_path not in existing_paths:
                        # 新发现的视频
                        video_id = str(uuid.uuid4())
                        now = datetime.now().isoformat()

                        try:
                            file_size = file_path.stat().st_size
                        except (OSError, PermissionError):
                            file_size = 0

                        video_info = {
                            "id": video_id,
                            "project_id": project_id,
                            "name": file_path.stem,
                            "path": str_path,
                            "size": file_size,
                            "duration": 0.0,
                            "format": file_path.suffix.lstrip(".").lower(),
                            "imported_at": now,
                            "metadata": {}
                        }

                        self.db.add_video(video_info)
                        found_count += 1
                        logger.info(f"[DB] Discovered new video: {file_path.name}")
        except (OSError, PermissionError) as e:
            logger.error(f"Failed to scan videos directory: {e}")

        # 检查缺失的视频（标记为 missing，但不删除）
        missing_count = 0
        for path in scanned_paths:
            if not Path(path).exists():
                missing_count += 1

        # 更新项目视频数量
        video_count = self.db.get_video_count(project_id)
        self.db.update_project(project_id, {"episode_count": video_count})

        if found_count > 0 or missing_count > 0:
            logger.info(
                f"[DB] Sync result for {project_id}: "
                f"+{found_count} new, {missing_count} missing"
            )

        return {
            "found": found_count,
            "removed": 0,
            "missing": missing_count,
        }

def update_project(self, project_id: str, updates: Dict[str, Any]) -> Optional[ProjectMeta]:
        """更新项目元数据"""
        result = self.db.update_project(project_id, updates)
        if result:
            return ProjectMeta(**result)
        return None

def get_manager() -> ProjectManager:
    """获取全局项目管理器"""
    global _manager
    if _manager is None:
        _manager = ProjectManager()
    return _manager

