import { ipcMain, BrowserWindow, dialog, app, shell } from 'electron';
import * as fs from 'fs';
import * as path from 'path';
import { IPC_CHANNELS } from './channels';
import { BackendManager } from '../backend/manager';
import { DialogService } from '../services/dialog';
import { WindowManager } from '../window/manager';

// 获取后端管理器实例（从 app.ts 导入）
let backendManager: BackendManager | null = null;
let windowManager: WindowManager | null = null;

export function setBackendManager(manager: BackendManager): void {
  backendManager = manager;
}

export function setWindowManager(manager: WindowManager): void {
  windowManager = manager;
}

function getMainWindow(): BrowserWindow | null {
  return BrowserWindow.getAllWindows()[0] || null;
}

function forwardProgress(payload: unknown): void {
  const mainWindow = getMainWindow();
  if (mainWindow) {
    mainWindow.webContents.send(IPC_CHANNELS.BACKEND_PROGRESS, payload);
  }
}

function forwardLog(message: string, level: string): void {
  const mainWindow = getMainWindow();
  if (mainWindow) {
    mainWindow.webContents.send(IPC_CHANNELS.BACKEND_LOG, message, level);
  }
}

export function setupIpcHandlers(): void {
  // ============= 对话框处理器 =============
  ipcMain.handle(IPC_CHANNELS.DIALOG_OPEN_FILE, async (_event, options) => {
    return DialogService.openFile(options);
  });

  ipcMain.handle(IPC_CHANNELS.DIALOG_OPEN_FOLDER, async (_event, options) => {
    return DialogService.openFolder(options);
  });

  ipcMain.handle(IPC_CHANNELS.DIALOG_SAVE_FILE, async (_event, options) => {
    return DialogService.saveFile(options);
  });

  // ============= 后端调用处理器 =============
  ipcMain.handle(IPC_CHANNELS.BACKEND_CALL, async (_event, method: string, params?: Record<string, unknown>) => {
    console.log(`[Main][IpcBridge] backend:call → method=${method}`, params ?? {});

    if (!backendManager) {
      return {
        success: false,
        error: { code: -32001, message: 'Backend not initialized', data: null },
      };
    }

    try {
      const result = await backendManager.call(method, params);
      return { success: true, data: result };
    } catch (error) {
      return {
        success: false,
        error: {
          code: -32001,
          message: error instanceof Error ? error.message : 'Unknown error',
          data: error,
        },
      };

    return { success: true, data: result };
  } catch (error) {
    return {
      success: false,
      error: {
        code: -32001,
        message: error instanceof Error ? error.message : 'Unknown error',
        data: error,
      },
    };
  }
});

// ============= 窗口控制处理器 =============
ipcMain.handle(IPC_CHANNELS.WINDOW_MINIMIZE, () => {
  const mainWindow = getMainWindow();
  if (mainWindow) {
    mainWindow.minimize();
  }
});

ipcMain.handle(IPC_CHANNELS.WINDOW_MAXIMIZE, () => {
  const mainWindow = getMainWindow();
  if (mainWindow) {
    if (mainWindow.isMaximized()) {
      mainWindow.unmaximize();
    } else {
      mainWindow.maximize();
    }
  }
});

ipcMain.handle(IPC_CHANNELS.WINDOW_CLOSE, () => {
  const mainWindow = getMainWindow();
  if (mainWindow) {
    mainWindow.close();
  }
});

// ============= 系统处理器 =============
ipcMain.handle(IPC_CHANNELS.SYSTEM_GET_VERSION, () => {
  return {
    success: true,
    data: {
      version: app.getVersion(),
      name: app.getName(),
    },
  };
});

ipcMain.handle(IPC_CHANNELS.SYSTEM_GET_FFMPEG_INFO, async () => {
  if (!backendManager) {
    return {
      success: false,
      error: { code: -32001, message: 'Backend not initialized', data: null },
    };
  }

  try {
    const result = await backendManager.call('system.getFFmpegInfo', {});
    return { success: true, data: result };
  } catch (error) {
    return {
      success: false,
      error: {
        code: -32001,
        message: error instanceof Error ? error.message : 'Failed to get FFmpeg info',
        data: error,
      },
    };
  }
});

// ============= 打开文件路径 =============
ipcMain.handle(IPC_CHANNELS.SYSTEM_OPEN_PATH, async (_event, filePath: string) => {
  try {
    await shell.openPath(filePath);
    return { success: true };
  } catch (error) {
    return {

    }
  });

  // ============= 打开文件路径 =============
  ipcMain.handle(IPC_CHANNELS.SYSTEM_OPEN_PATH, async (_event, filePath: string) => {
    try {
      await shell.openPath(filePath);
      return { success: true };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to open path',
      };
    }
  });

  // ============= 文件系统 - 扫描目录（递归扫描包括子目录）============
  ipcMain.handle(IPC_CHANNELS.FS_SCAN_DIRECTORY, async (_event, dirPath: string) => {
    try {
      const videoExtensions = ['.mp4', '.mov', '.avi', '.mkv', '.wmv', '.webm', '.flv'];
      const videoFiles: string[] = [];

      // 递归扫描目录
      const scanDirectory = async (currentPath: string) => {
        const entries = await fs.promises.readdir(currentPath, { withFileTypes: true });

        for (const entry of entries) {
          const fullPath = path.join(currentPath, entry.name);

          if (entry.isFile()) {
            const ext = path.extname(entry.name).toLowerCase();
            if (videoExtensions.includes(ext)) {
              videoFiles.push(fullPath);
            }
          } else if (entry.isDirectory()) {
            // 递归扫描子目录
            await scanDirectory(fullPath);
          }
        }
      };

      await scanDirectory(dirPath);
      return { success: true, data: videoFiles };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to scan directory',
      };
    }
  });

  console.log('[Main][IpcBridge] IPC handlers registered');
}

function formatTime(seconds: number): string {
  if (!isFinite(seconds) || seconds < 0) return '0:00';
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  if (h > 0) {
    return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  }
  return `${m}:${s.toString().padStart(2, '0')}`;
}

interface MiniPreviewProps {
  filePath: string;
  width?: number;
  height?: number;
  startTime?: number;
  endTime?: number;
  onClick?: () => void;
}

MiniPreview: React.FC<MiniPreviewProps> = ({
  filePath,
  width = 160,
  height = 90,
  startTime,
  endTime,
  onClick,
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handleLoaded = () => {
      setLoaded(true);
      // 跳到 startTime 或 1 秒处获取缩略图帧
      const seekTime = startTime != null && startTime > 0 ? startTime : 1;
      video.currentTime = seekTime;
    };

    const handleError = () => setError(true);

    video.addEventListener('loadedmetadata', handleLoaded);
    video.addEventListener('error', handleError);

    return () => {
      video.removeEventListener('loadedmetadata', handleLoaded);
      video.removeEventListener('error', handleError);
    };
  }, [startTime]);

  // 到达 seek 位置后暂停
  useEffect(() => {
    const video = videoRef.current;
    if (!video || !loaded) return;

    const handleSeeked = () => {
      video.pause();
    };

    video.addEventListener('seeked', handleSeeked);
    return () => video.removeEventListener('seeked', handleSeeked);
  }, [loaded]);

  if (error) {
    return (
      <div
        style={{
          width, height, borderRadius: 8,
          background: 'rgba(255,255,255,0.04)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          cursor: onClick ? 'pointer' : 'default',
        }}
        onClick={onClick}
      >
        <PlayCircleOutlined style={{ fontSize: 20, color: '#4a5a7a' }} />
      </div>
    );
  }

  return (
    <div
      style={{
        width, height, borderRadius: 8, overflow: 'hidden',
        position: 'relative', cursor: onClick ? 'pointer' : 'default',
        background: '#000',
      }}
      onClick={onClick}
    >
      <video
        ref={videoRef}
        src={videoUrl(filePath)}
        preload="metadata"
        muted
        playsInline
        style={{
          width: '100%', height: '100%', objectFit: 'cover',
          opacity: loaded ? 1 : 0,
          transition: 'opacity 0.3s',
        }}
      />
      {/* 播放按钮覆盖层 */}
      <div style={{
        position: 'absolute', inset: 0,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        background: 'rgba(0,0,0,0.25)',
        opacity: 0, transition: 'opacity 0.2s',
      }}
        className="mini-preview-overlay"
      />
      {!loaded && (
        <div style={{
          position: 'absolute', inset: 0,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          background: 'rgba(255,255,255,0.04)',
        }}>
          <PlayCircleOutlined style={{ fontSize: 20, color: '#4a5a7a' }} />
        </div>
      )}
      {/* 时间范围标签 */}
      {startTime != null && endTime != null && (
        <div style={{
          position: 'absolute', bottom: 4, right: 4,
          padding: '1px 6px', borderRadius: 4,
          background: 'rgba(0,0,0,0.7)',
          color: '#c8d0dc', fontSize: 10,
          fontFamily: "'JetBrains Mono', monospace",
        }}>
          {formatTime(endTime - startTime)}
        </div>
      )}
    </div>
  );
}

